head.script:
scwin.fireOver = function(node) {
    if (document.createEventObject) {
        node.fireEvent('onmouseover');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('mouseover', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.onmouseover == 'function') {
        node.onmouseover();
    }
}
scwin.mouseOverBehaviour = function(id) {
    var img = WebSquare.wUnit.getDomById($p.id + id);
    var img1 = img.getElementsByTagName("tr")[0];
    var img2 = img1.getElementsByTagName("td")[1];
    scwin.fireOver(img2);
}
scwin.checkValue = function(id, value) {
    if (WebSquare.wUnit.getDomById($p.id + id).innerText == value) {
        return true;
    }
    return false
}
scwin.checkNotDisplay = function(id) {
    if (WebSquare.wUnit.getDomById($p.id + id) == null) {
        return true;
    }
    return false
}
scwin.unitTest = function() {
    //init
    // WebSquare.wUnit.start();
    //Test step 1. 샘플실행 후 tooltipDisplay=true 부분의 값에 마우스를 오버한다.
    //1. After executing the sample, mouse over the value of the tooltipDisplay = true part.
    //Verify step 1. The "1234567890" value is shown as a tooltip (normal)
    WebSquare.wUnit.addCommand("set", "scwin.mouseOverBehaviour('checkbox4')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkValue('checkbox4_tooltip', '1234567890')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. tooltipDisplay=true, tooltipItemLabel=tooltip 부분의 값에 마우스를 오버한다.
    //2. Move the mouse over the value of tooltipDisplay = true, tooltipItemLabel = tooltip.
    //Verify step 2. The 'tooltip' value is shown as a tooltip (normal)
    WebSquare.wUnit.addCommand("set", "scwin.mouseOverBehaviour('checkbox5')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkValue('checkbox5_tooltip', 'tooltip')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 3. elipsis 적용 안된경우 부분의 값에 마우스를 오버한다.
    //3. If you do not apply elipsis, mouse over the value of the part.
    //Verify step 3. Tooltip is not shown (normal)
    WebSquare.wUnit.addCommand("set", "scwin.mouseOverBehaviour('checkbox6')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkNotDisplay('checkbox6_tooltip')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 23-Feb-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
